<template>
 <section class="maa-log-viewer" :class="{'options-expanded':optionsExpanded}" aria-label="MAA 日志面板">
  <header class="log-heading"><strong>运行日志</strong><span class="log-connection" :class="connection">{{connectionLabel}}</span><span class="log-count">{{filtered.length}} / {{entries.length}} 条</span></header>
  <div class="log-filters">
   <input v-model="query" type="search" maxlength="256" aria-label="搜索 MAA 日志" placeholder="搜索内容、任务或时间"/>
   <select v-model="level" aria-label="日志级别"><option value="all">全部级别</option><option value="issues">警告和错误</option><option v-for="(label,key) in logLevelLabels" :key="key" :value="key">{{label}}</option></select>
   <select v-model="task" aria-label="日志任务"><option value="all">全部任务</option><option v-if="task!=='all'&&!taskOptions.includes(task)" :value="task">{{task}}（暂无日志）</option><option v-for="name in taskOptions" :value="name" :key="name">{{name}}</option></select>
  </div>
  <div class="log-toolbar">
   <button type="button" :aria-pressed="following" class="log-follow" :class="{active:following}" @click="toggleFollow">{{following?'跟随最新':'已暂停'}}<span v-if="unread"> · {{unread}} 条新日志</span></button>
   <div class="log-extra"><button type="button" :aria-pressed="wrap" @click="wrap=!wrap">换行{{wrap?'：开':'：关'}}</button>
   <button type="button" :aria-pressed="rawMode" @click="rawMode=!rawMode">原文{{rawMode?'：开':'：关'}}</button>

   <details ref="exportMenu" class="log-export"><summary>导出</summary><div><button type="button" :disabled="!filtered.length" @click="download(false)">导出筛选结果</button><button type="button" :disabled="!entries.length" @click="download(true)">导出全部原文</button></div></details>
   <button type="button" :disabled="!entries.length" title="仅清空本页缓存，不停止任务或删除服务端日志" @click="clearView">清空视图</button></div><button type="button" :disabled="!filtered.length" @click="copyVisible">复制</button><button type="button" class="log-options-toggle" :aria-expanded="optionsExpanded" @click="optionsExpanded=!optionsExpanded">{{optionsExpanded?'收起工具':'筛选与工具'}}</button>
  </div>
  <div class="log-summary"><button type="button" :aria-pressed="level==='error'" @click="level=level==='error'?'all':'error'" class="error">错误 {{counts.error}}</button><button type="button" :aria-pressed="level==='warning'" @click="level=level==='warning'?'all':'warning'" class="warning">警告 {{counts.warning}}</button><span>{{following?'新日志自动跟随':'阅读中，已暂停自动滚动'}}</span></div>
  <div ref="viewport" class="log-viewport" :class="{nowrap:!wrap}" tabindex="0" aria-label="MAA 实时日志" @scroll.passive="onScroll">
   <ol v-if="filtered.length" class="log-rows"><li v-for="entry in filtered" :key="entry.id" class="log-row" :class="[entry.level,{'task-start':entry.taskStart}]">
    <time :datetime="entry.time||undefined" :title="entry.time">{{entry.clock||'—'}}</time><span class="log-level">{{logLevelLabels[entry.level]}}</span><div class="log-content"><span v-if="entry.task" class="log-task">{{entry.task}}</span><span class="log-text">{{rawMode?stripLogAnsi(entry.raw):entry.text}}</span><span v-if="entry.truncated" class="log-truncated">（单条内容过长，已截断）</span></div>
   </li></ol>
   <div v-else class="log-empty">{{entries.length?'没有匹配的日志，试试调整搜索或筛选条件。':'等待运行日志…'}}<button v-if="entries.length" type="button" @click="resetFilters">重置筛选</button></div>
  </div>
  <button v-if="!following&&unread" type="button" class="log-new" @click="resume">查看 {{unread}} 条新日志 ↓</button>
  <div v-if="copyFallback" class="log-copy-fallback"><label>待复制日志<textarea ref="copyArea" readonly :value="copyFallback" /></label><button type="button" @click="copyFallback=''">关闭待复制文字</button></div>
  <footer class="log-footer" role="status">{{notice|| (connection==='reconnecting'?'日志正在重连，后台任务会继续运行。':`保留最近 ${limit} 条日志，重要记录请及时导出。`)}}</footer>
 </section>
</template>
<script setup>
import {ref,computed,watch,nextTick,onMounted,onUnmounted} from 'vue'
import {filterMaaLogs,formatMaaLogs,logLevelLabels,MAA_LOG_LIMIT,stripLogAnsi} from '@/plugins/maa/utils/maaLogs'
const props=defineProps({entries:{type:Array,default:()=>[]},connection:{type:String,default:'connecting'},limit:{type:Number,default:MAA_LOG_LIMIT}})
const emit=defineEmits(['clear'])
const optionsExpanded=ref(false),query=ref(''),level=ref('all'),task=ref('all'),wrap=ref(true),rawMode=ref(false),pauseReason=ref(null),unread=ref(0),notice=ref(''),copyFallback=ref(''),viewport=ref(null),copyArea=ref(null),exportMenu=ref(null)
const following=computed(()=>pauseReason.value===null),filtered=computed(()=>filterMaaLogs(props.entries,{query:query.value,level:level.value,task:task.value}))
const taskOptions=computed(()=>[...new Set(props.entries.map(row=>row.task).filter(Boolean))])
const counts=computed(()=>props.entries.reduce((all,row)=>{if(row.level in all)all[row.level]++;return all},{error:0,warning:0}))
const connectionLabel=computed(()=>({connecting:'连接中',connected:'实时连接',reconnecting:'重连中',offline:'未连接'}[props.connection]||'连接中'))
let autoScrolling=false,observer,noticeTimer,lastId=props.entries.at(-1)?.id||0,disposed=false,scrollFrame
function say(text){notice.value=text;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.value='',5000)}
async function scrollLatest(){autoScrolling=true;await nextTick();if(disposed)return;const el=viewport.value;if(el&&el.clientHeight)el.scrollTop=el.scrollHeight;cancelAnimationFrame(scrollFrame);scrollFrame=requestAnimationFrame(()=>autoScrolling=false)}
function onScroll(){if(autoScrolling||!viewport.value)return;const el=viewport.value,distance=el.scrollHeight-el.scrollTop-el.clientHeight;if(distance>40&&following.value)pauseReason.value='scroll';else if(distance<=16&&pauseReason.value==='scroll')resume()}
function resume(){pauseReason.value=null;unread.value=0;scrollLatest()}
function toggleFollow(){if(following.value)pauseReason.value='manual';else resume()}
function resetFilters(){query.value='';level.value='all';task.value='all'}
function clearView(){emit('clear');unread.value=0;copyFallback.value='';say('已清空本页日志；后台任务继续运行。')}
watch(()=>props.entries.at(-1)?.id||0,id=>{if(!id){lastId=0;return}if(!following.value)unread.value+=filtered.value.filter(row=>row.id>lastId).length;lastId=id;if(following.value)scrollLatest()},{flush:'post'})
watch([query,level,task,wrap,rawMode],()=>{unread.value=0;if(following.value)scrollLatest();else nextTick(()=>{if(viewport.value)viewport.value.scrollTop=0})})
function selectionChanged(){const selection=window.getSelection();if(selection&&!selection.isCollapsed&&viewport.value?.contains(selection.anchorNode))pauseReason.value='manual'}
async function copyVisible(){const text=formatMaaLogs(filtered.value,rawMode.value);try{if(!navigator.clipboard?.writeText)throw Error();await navigator.clipboard.writeText(text);say(`已复制 ${filtered.value.length} 条日志`)}catch{copyFallback.value=text;await nextTick();copyArea.value?.focus();copyArea.value?.select();say('自动复制被浏览器阻止，请长按或按 Ctrl+C 复制。')}}
function download(all){const rows=all?props.entries:filtered.value;const url=URL.createObjectURL(new Blob([formatMaaLogs(rows,all||rawMode.value)],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='maa-log-'+(all?'all-':'filtered-')+new Date().toISOString().replace(/[:.]/g,'-')+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);if(exportMenu.value)exportMenu.value.open=false;say(`已导出 ${rows.length} 条日志`)}
onMounted(()=>{observer=new ResizeObserver(()=>{if(following.value)scrollLatest()});if(viewport.value)observer.observe(viewport.value);document.addEventListener('selectionchange',selectionChanged);scrollLatest()})
onUnmounted(()=>{disposed=true;observer?.disconnect();clearTimeout(noticeTimer);cancelAnimationFrame(scrollFrame);document.removeEventListener('selectionchange',selectionChanged)})
</script>
<style scoped>
.maa-log-viewer{position:relative;display:flex;flex-direction:column;flex:1;min-width:0;min-height:0;border:1px solid #34485c;border-radius:10px;background:#101b28;color:#ccdae8;overflow:hidden;container:maa-log / inline-size}
.log-heading{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:10px 12px 5px;flex:none}.log-heading strong{font-size:13px;font-weight:600}.log-count{margin-left:auto;color:#93a9bc;font-size:11px}.log-connection{font-size:10px;color:#d6b782}.log-connection.connected{color:#8ddbc0}.log-connection.reconnecting{color:#efc07d}
.log-filters{display:flex;flex-wrap:wrap;gap:6px;padding:6px 10px;flex:none}.log-filters input{flex:1 1 150px;width:100px}.log-filters select{flex:1 1 100px;width:100px}.maa-log-viewer .log-filters :is(input,select){background:#142638;border:1px solid #38526a;border-radius:7px;min-width:0;min-height:34px;color:#d9eaf7;font:inherit;font-size:12px;max-width:100%}
.maa-log-viewer.options-expanded{overflow-y:auto}.log-extra{display:contents}.maa-log-viewer .log-options-toggle{display:none}.log-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:5px;padding:4px 10px 7px;flex:none}.maa-log-viewer button,.maa-log-viewer summary{min-height:32px;padding:5px 8px;border:1px solid #344f65;border-radius:6px;background:#192e41;color:#bcd5e9;font:inherit;font-size:11px;cursor:pointer;touch-action:manipulation}.maa-log-viewer button.active,.maa-log-viewer button[aria-pressed=true]{color:#a2e0ff;background:#1c4158;border-color:#4085a7}.maa-log-viewer button:disabled{opacity:.4;cursor:not-allowed}.maa-log-viewer :is(button,summary,input,select):focus-visible{outline:2px solid #6fd4ff;outline-offset:-2px}.log-follow{margin-right:auto}
.log-export{position:relative}.log-export summary{display:flex;align-items:center;justify-content:center;list-style:none}.log-export summary::after{content:' ▾'}.log-export>div{position:absolute;right:0;top:calc(100% + 4px);z-index:10;min-width:150px;padding:6px;border:1px solid #47647d;border-radius:8px;background:#192d40;box-shadow:0 8px 24px #0007;display:grid;gap:5px}.log-export button{white-space:nowrap;text-align:left}
.log-summary{display:flex;align-items:center;flex-wrap:wrap;gap:6px;padding:4px 10px 8px;border-bottom:1px solid #2b4054;flex:none}.log-summary button{min-height:26px;padding:2px 7px;font-size:10px;background:transparent}.log-summary button.error{color:#ffafb8;border-color:#724550}.log-summary button.warning{color:#edcc8c;border-color:#695638}.log-summary>span{color:#859fb4;font-size:10px;margin-left:auto}
.log-viewport{flex:1;min-height:80px;overflow:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#45617a transparent;overflow-anchor:auto}.log-viewport:focus-visible{outline:2px solid #6fd4ff;outline-offset:-2px}.log-rows{list-style:none;padding:6px 0;margin:0;min-width:100%}.log-row{display:grid;grid-template-columns:60px 34px minmax(0,1fr);gap:6px;align-items:baseline;padding:5px 10px;border-left:2px solid transparent;font:12px/1.8 Consolas,'Microsoft YaHei',monospace}.log-row:nth-child(even){background:#ffffff03}.log-row>time{font-size:10px;color:#8199ad;font-variant-numeric:tabular-nums}.log-level{font-size:10px;text-align:center;color:#9db4c9}.log-content{min-width:0;white-space:pre-wrap;overflow-wrap:anywhere;user-select:text}.log-task{font:10px/1.4 system-ui,sans-serif;color:#8fc9e9;border:1px solid #35566b;border-radius:4px;padding:1px 4px;margin-right:7px;display:inline-block;vertical-align:baseline}.log-row.warning{border-left-color:#bf9346;background:#5f45131a}.log-row.warning :is(.log-level,.log-text){color:#f0d08e}.log-row.error{border-left-color:#db7285;background:#82334720}.log-row.error :is(.log-level,.log-text){color:#ffbac4}.log-row.success :is(.log-level,.log-text){color:#9bdbc2}.log-row.debug{color:#8fa2b4}.log-row.task-start{border-top:1px solid #3b576d;margin-top:8px;padding-top:10px;background:#15374c40}.log-truncated{font-size:10px;color:#d5b583}.nowrap .log-row{grid-template-columns:60px 34px auto;width:max-content;min-width:100%}.nowrap .log-content{white-space:pre;overflow-wrap:normal}.log-empty{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;min-height:150px;padding:22px;color:#91a9bd;font-size:12px;text-align:center}.log-new{position:absolute;bottom:33px;left:50%;transform:translateX(-50%);box-shadow:0 4px 15px #0008;white-space:nowrap}.log-footer{flex:none;padding:6px 10px;color:#8ca5ba;font-size:10px;line-height:1.5;border-top:1px solid #293f51;overflow-wrap:anywhere}.log-copy-fallback{flex:none;max-height:160px;overflow:auto;padding:8px;font-size:11px}.log-copy-fallback textarea{display:block;width:100%;min-height:70px;resize:vertical;background:#0d1823;color:#c9e4f7;font:12px/1.6 monospace}
@container maa-log (max-width:450px){.maa-log-viewer .log-options-toggle{display:block}.maa-log-viewer:not(.options-expanded) .log-filters select,.maa-log-viewer:not(.options-expanded) .log-extra{display:none}.log-extra{display:flex;flex-wrap:wrap;gap:5px;order:4;flex-basis:100%}.log-toolbar{gap:6px}.log-extra .log-export>div{position:static;box-shadow:none}.options-expanded{overflow-y:auto}.options-expanded .log-viewport{flex:none;min-height:180px;height:180px}.log-heading{padding-top:8px}.log-filters input{flex-basis:100%}.log-row{grid-template-columns:54px 30px minmax(0,1fr);gap:4px;padding-left:6px;padding-right:6px}.log-connection{font-size:11px}.log-row{font-size:13px}.log-heading{padding-left:9px;padding-right:9px}}
@media(pointer:coarse){.maa-log-viewer button,.maa-log-viewer summary{min-height:40px}.maa-log-viewer .log-filters :is(input,select){min-height:40px;font-size:16px}.log-summary button{min-height:32px}}
</style>
